UseTemplate.TOOLTIP_VAL_CODE:
(L:P21_FIRE_L_ENG) 0 == if{
		'Normal'
} els{
		'PUSHED - L engine isolated, bottles armed'
}

UseTemplate.ONUPDATE_CODE:
(L:P21_FIRE_L_ENG) 1 ==
if{
	(L:P21_FIRE_L_ENG_DONE) 0 ==
	if{
		1 (>L:P21_FIRE_L_ENG_DONE)
		(A:GENERAL ENG FUEL VALVE:1, Bool) if{ (>K:TOGGLE_FUEL_VALVE_ENG1) }
		0 (>K:MIXTURE1_SET)
		0 (>L:P21_LBLEED_BTN)
		0 (>L:P21_HYD_L_SOV_BTN)
		(A:GENERAL ENG MASTER ALTERNATOR:1, Bool) if{ 1 (>K:TOGGLE_MASTER_ALTERNATOR) }
	}
} els{

	(L:P21_FIRE_L_ENG_DONE) 1 ==
	if{
		1 (>L:P21_FIRE_L_ENG)
	}
}

UseTemplate.TOOLTIP_VAL_CODE:
(L:P21_FIRE_R_ENG) 0 == if{
		'Normal'
} els{
		'PUSHED - R engine isolated, bottles armed'
}

UseTemplate.ONUPDATE_CODE:
(L:P21_FIRE_R_ENG) 1 ==
if{
	(L:P21_FIRE_R_ENG_DONE) 0 ==
	if{
		1 (>L:P21_FIRE_R_ENG_DONE)
		(A:GENERAL ENG FUEL VALVE:2, Bool) if{ (>K:TOGGLE_FUEL_VALVE_ENG2) }
		0 (>K:MIXTURE2_SET)
		0 (>L:P21_RBLEED_BTN)
		0 (>L:P21_HYD_R_SOV_BTN)
		(A:GENERAL ENG MASTER ALTERNATOR:2, Bool) if{ 2 (>K:TOGGLE_MASTER_ALTERNATOR) }
	}
} els{

	(L:P21_FIRE_R_ENG_DONE) 1 ==
	if{
		1 (>L:P21_FIRE_R_ENG)
	}
}

UseTemplate.TOOLTIP_VAL_CODE:
(L:P21_FIRE_APU) 0 == if{
		'Normal'
} els{
		'PUSHED - APU isolated, bottle 2 armed'
}

(L:P21_FIREX_BTL1_SPENT) 1 == if{
		'DISCHARGED'
} els{
	(L:P21_FIRE_L_ENG) (L:P21_FIRE_R_ENG) or 1 == if{
			'ARMED'
	} els{
			'Not armed'
	}
}

(L:P21_FIREX_BTL2_SPENT) 1 == if{
		'DISCHARGED'
} els{
	(L:P21_FIRE_L_ENG) (L:P21_FIRE_R_ENG) or (L:P21_FIRE_APU) or 1 == if{
			'ARMED'
	} els{
			'Not armed'
	}
}

UseTemplate.UPDATE_CODE:
(L:P21_FIRE_APU_DETECTED) 1 ==
(A:SIM ON GROUND, Bool) and
(L:P21_FIREX_BTL2_SPENT) 0 == and
if{
	(L:P21_FIREX_APU_AUTO_T) (E:SIMULATION DELTA TIME, seconds) + (>L:P21_FIREX_APU_AUTO_T)
	(L:P21_FIREX_APU_AUTO_T) 5 >
	if{
		1 (>L:P21_FIREX_BTL2_SPENT)
		1 (>L:P21_FIRE_APU)
	}
} els{
	0 (>L:P21_FIREX_APU_AUTO_T)
}

UseTemplate.TOOLTIP_VAL_CODE:
(L:P21_SYS_TEST_KNOB) 1 == if{ 'ANNUN A' } els{
(L:P21_SYS_TEST_KNOB) 2 == if{ 'ANNUN B' } els{
(L:P21_SYS_TEST_KNOB) 3 == if{ 'PROBES' } els{
(L:P21_SYS_TEST_KNOB) 4 == if{ 'STALL/RUD LIM' } els{
(L:P21_SYS_TEST_KNOB) 5 == if{ 'ICE DET' } els{
(L:P21_SYS_TEST_KNOB) 6 == if{
	(L:P21_FIRE_TEST_RUN) 1 == if{ 'FIRE DET - TESTING' } els{
	(L:P21_FIRE_TEST_OK) 1 == if{ 'FIRE DET - TEST OK' } els{ 'FIRE DET - click to test' } }
} els{
(L:P21_SYS_TEST_KNOB) 7 == if{ 'TAWS' } els{ 'OFF' } } } } } } }

UseTemplate.UPDATE_CODE:
(L:P21_SYS_TEST_KNOB) 6 !=
if{
	0 (>L:P21_FIRE_TEST_RUN)
	0 (>L:P21_FIRE_TEST_OK)
	0 (>L:P21_FIRE_TEST_T)
} els{
	(L:P21_FIRE_TEST_RUN) 1 ==
	if{
		(L:P21_FIRE_TEST_T) (E:SIMULATION DELTA TIME, seconds) + (>L:P21_FIRE_TEST_T)
		(L:P21_FIRE_TEST_T) 10 >
		if{
			0 (>L:P21_FIRE_TEST_RUN)
			1 (>L:P21_FIRE_TEST_OK)
		}
	}
}
